import { CATALOG_EXECUTOR_METHODS } from '../core/catalogPort'
import type { RuntimeContext } from '../core/runtime'
import type { GetProductInput, SearchProductsInput } from '../core/catalogTypes'
import { createSalesforceCatalogService, type SalesforceCatalogOptions } from './catalogService'

/**
 * Server half of the BFF pattern: a Node-style request handler that fronts
 * the Salesforce catalog service. Mount it on one POST route (default
 * /api/catalog) and point createHttpCatalogService (./http subpath) at it —
 * Salesforce credentials stay on the server; the browser only ever sees
 * catalog DTOs. Works as a Vercel function, Express route, or Vite dev
 * middleware.
 */

/** Minimal structural request/response shapes — no Node type dependency. */
export interface CatalogHandlerRequest {
  method?: string
  /** Pre-parsed body when the host framework provides one (Vercel does). */
  body?: unknown
}
export interface CatalogHandlerResponse {
  statusCode: number
  setHeader(name: string, value: string): void
  end(chunk?: string): void
}
export type SalesforceCatalogHandler = (
  req: CatalogHandlerRequest,
  res: CatalogHandlerResponse,
) => Promise<void>

const readBody = async (req: CatalogHandlerRequest): Promise<Record<string, unknown>> => {
  if (req.body !== undefined && req.body !== null) {
    return (typeof req.body === 'string' ? JSON.parse(req.body) : req.body) as Record<string, unknown>
  }
  let raw = ''
  for await (const chunk of req as unknown as AsyncIterable<Buffer | string>) raw += chunk
  return raw ? (JSON.parse(raw) as Record<string, unknown>) : {}
}

const send = (res: CatalogHandlerResponse, status: number, body: unknown): void => {
  res.statusCode = status
  res.setHeader('Content-Type', 'application/json')
  res.end(JSON.stringify(body))
}

export function createSalesforceCatalogHandler(options: SalesforceCatalogOptions): SalesforceCatalogHandler {
  const service = createSalesforceCatalogService(options)

  return async (req, res) => {
    if (req.method !== 'POST') {
      send(res, 405, { error: 'Method not allowed — use POST with { method, payload }' })
      return
    }
    try {
      const { method, payload } = await readBody(req)
      const { context, ...input } = (payload ?? {}) as { context?: RuntimeContext } & Record<string, unknown>
      const ctx = context as RuntimeContext
      // Service methods never reject — failures come back as { status: 'error' }.
      switch (method) {
        case CATALOG_EXECUTOR_METHODS.searchProducts:
          send(res, 200, await service.searchProducts(ctx, input as unknown as SearchProductsInput))
          return
        case CATALOG_EXECUTOR_METHODS.getProduct:
          send(res, 200, await service.getProduct(ctx, input as unknown as GetProductInput))
          return
        case CATALOG_EXECUTOR_METHODS.listCategories:
          send(res, 200, await service.listCategories(ctx))
          return
        default:
          send(res, 400, { error: `Unknown catalog method: ${String(method)}` })
      }
    } catch (err) {
      send(res, 502, { error: err instanceof Error ? err.message : 'Catalog handler failed' })
    }
  }
}
