import type { CatalogService } from '../core/catalogPort'
import type { CatalogProduct, CatalogSort } from '../core/catalogTypes'
import { createSoqlRunner, escapeSoql, type SalesforceConnection } from './transport'

/**
 * CatalogService over standard Salesforce objects:
 *   product  = PricebookEntry joined to Product2 (standard pricebook)
 *   category = Product2.Family
 * Methods resolve (never reject) per the port contract — transport failures
 * surface as `{ status: 'error' }` and the UI degrades, never blanks.
 */
export interface SalesforceCatalogOptions extends SalesforceConnection {
  /** ISO 4217 currency for prices, default 'USD' (single-currency orgs). */
  currency?: string
}

interface PricebookEntryRecord {
  UnitPrice: number | null
  Product2: {
    Id: string
    Name: string
    ProductCode: string | null
    Description: string | null
    Family: string | null
    DisplayUrl: string | null
    IsActive: boolean
  }
}

const PRODUCT_FIELDS =
  'UnitPrice, Product2.Id, Product2.Name, Product2.ProductCode, Product2.Description, Product2.Family, Product2.DisplayUrl, Product2.IsActive'
const PRODUCT_FROM =
  'FROM PricebookEntry WHERE Pricebook2.IsStandard = true AND IsActive = true AND Product2.IsActive = true'

const ORDER_BY: Record<CatalogSort, string> = {
  relevance: 'Product2.Name ASC',
  name: 'Product2.Name ASC',
  'price-asc': 'UnitPrice ASC',
  'price-desc': 'UnitPrice DESC',
}

const errorMessageOf = (error: unknown): string =>
  error instanceof Error ? error.message : 'Salesforce catalog request failed'

export function createSalesforceCatalogService(options: SalesforceCatalogOptions): CatalogService {
  const soql = createSoqlRunner(options)
  const currency = options.currency ?? 'USD'

  const toProduct = (entry: PricebookEntryRecord): CatalogProduct => ({
    id: entry.Product2.Id,
    sku: entry.Product2.ProductCode ?? '',
    name: entry.Product2.Name,
    description: entry.Product2.Description ?? '',
    price: entry.UnitPrice ?? 0,
    currency,
    categoryId: entry.Product2.Family ?? undefined,
    imageUrl: entry.Product2.DisplayUrl ?? undefined,
    inStock: entry.Product2.IsActive,
  })

  return {
    async searchProducts(_context, input) {
      try {
        const filters: string[] = []
        const text = input.text.trim()
        if (text) {
          const like = `'%${escapeSoql(text)}%'`
          filters.push(`(Product2.Name LIKE ${like} OR Product2.ProductCode LIKE ${like})`)
        }
        if (input.categoryId) filters.push(`Product2.Family = '${escapeSoql(input.categoryId)}'`)
        const where = filters.length ? ` AND ${filters.join(' AND ')}` : ''

        const [count, page] = await Promise.all([
          soql<never>(`SELECT COUNT() ${PRODUCT_FROM}${where}`),
          soql<PricebookEntryRecord>(
            `SELECT ${PRODUCT_FIELDS} ${PRODUCT_FROM}${where}` +
              ` ORDER BY ${ORDER_BY[input.sort] ?? ORDER_BY.relevance}` +
              ` LIMIT ${input.pageSize} OFFSET ${(input.page - 1) * input.pageSize}`,
          ),
        ])
        return { status: 'success', products: page.records.map(toProduct), totalCount: count.totalSize }
      } catch (error) {
        return { status: 'error', errorMessage: errorMessageOf(error), products: [], totalCount: 0 }
      }
    },

    async getProduct(_context, input) {
      try {
        const result = await soql<PricebookEntryRecord>(
          `SELECT ${PRODUCT_FIELDS} ${PRODUCT_FROM} AND Product2.Id = '${escapeSoql(input.productId)}' LIMIT 1`,
        )
        const entry = result.records[0]
        if (!entry) return { status: 'error', errorMessage: `Unknown product ${input.productId}` }
        return { status: 'success', product: toProduct(entry) }
      } catch (error) {
        return { status: 'error', errorMessage: errorMessageOf(error) }
      }
    },

    async listCategories(_context) {
      try {
        const result = await soql<{ Family: string | null }>(
          `SELECT Product2.Family Family ${PRODUCT_FROM} AND Product2.Family != null GROUP BY Product2.Family`,
        )
        return {
          status: 'success',
          categories: result.records
            .filter((record): record is { Family: string } => Boolean(record.Family))
            .map((record) => ({ id: record.Family, label: record.Family })),
        }
      } catch (error) {
        return { status: 'error', errorMessage: errorMessageOf(error), categories: [] }
      }
    },
  }
}
