import type { AddressService } from '../core/port'
import type { AddressDTO, SavedAddress } from '../core/types'
import { normalizeAddress, validateAddressFormat } from '../core/validation'
import { createSoqlRunner, escapeSoql, type SalesforceConnection } from './transport'

/**
 * AddressService over standard Salesforce objects.
 *
 * - listSavedAddresses: the account's Billing/Shipping compound addresses
 *   (account id from RuntimeContext.identity.accountId; empty for guests).
 * - searchAddresses/resolveAddress: not provided by Salesforce — they return
 *   `{ status: 'error' }`, which the composable treats as a provider outage
 *   and falls back to manual entry. Checkout is never blocked.
 * - validateAddress: core's offline format validation (US ZIP / CA postal).
 */
export type SalesforceAddressOptions = SalesforceConnection

interface AccountRecord {
  Id: string
  Name: string
  BillingStreet: string | null
  BillingCity: string | null
  BillingState: string | null
  BillingPostalCode: string | null
  BillingCountry: string | null
  ShippingStreet: string | null
  ShippingCity: string | null
  ShippingState: string | null
  ShippingPostalCode: string | null
  ShippingCountry: string | null
}

const toAddress = (
  record: AccountRecord,
  prefix: 'Billing' | 'Shipping',
): AddressDTO | null => {
  const street = record[`${prefix}Street`]
  if (!street) return null
  return {
    street,
    city: record[`${prefix}City`] ?? '',
    state: record[`${prefix}State`] ?? '',
    zip: record[`${prefix}PostalCode`] ?? '',
    country: record[`${prefix}Country`] ?? '',
  }
}

export function createSalesforceAddressService(options: SalesforceAddressOptions): AddressService {
  const soql = createSoqlRunner(options)

  return {
    async searchAddresses() {
      return {
        status: 'error',
        errorMessage: 'Address search is not available — enter the address manually.',
        suggestions: [],
      }
    },

    async resolveAddress() {
      return { status: 'error', errorMessage: 'Address search is not available.' }
    },

    async validateAddress(_context, input) {
      const normalized = normalizeAddress(input.address)
      const issues = validateAddressFormat(normalized, input.addressType)
      return { status: 'success', valid: Object.keys(issues).length === 0, issues, normalized }
    },

    async listSavedAddresses(context, input) {
      const accountId = context.identity.accountId
      if (!accountId) return { status: 'success', addresses: [] }
      try {
        const result = await soql<AccountRecord>(
          'SELECT Id, Name, BillingStreet, BillingCity, BillingState, BillingPostalCode, BillingCountry, ' +
            'ShippingStreet, ShippingCity, ShippingState, ShippingPostalCode, ShippingCountry ' +
            `FROM Account WHERE Id = '${escapeSoql(accountId)}' LIMIT 1`,
        )
        const record = result.records[0]
        if (!record) return { status: 'success', addresses: [] }

        const addresses: SavedAddress[] = []
        const billing = toAddress(record, 'Billing')
        const shipping = toAddress(record, 'Shipping')
        // Billing type prefers the billing address first; everything else shipping first.
        const ordered =
          input.addressType === 'billing'
            ? [{ kind: 'Billing', address: billing }, { kind: 'Shipping', address: shipping }]
            : [{ kind: 'Shipping', address: shipping }, { kind: 'Billing', address: billing }]
        for (const { kind, address } of ordered) {
          if (address) {
            addresses.push({ id: `${record.Id}-${kind}`, label: `${record.Name} — ${kind}`, address })
          }
        }
        return { status: 'success', addresses }
      } catch (error) {
        const errorMessage =
          error instanceof Error ? error.message : 'Saved address lookup failed'
        return { status: 'error', errorMessage, addresses: [] }
      }
    },
  }
}
